  (* [comment removed for export] *)
  Definition fr2_XS (ff fp : Z) : list (Z * Z) := [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 256); (sh ff, sh ff + 32)]%Z.

  Lemma fr2_XS_scratch : forall LF ff fp, fresh_frame H LF 2 ff fp -> Forall (fs_scratch H LF) (fr2_XS ff fp).
  Proof.
    intros LF ff fp FF. pose proof (fs_scratch_of_fresh H _ _ _ _ FF) as FX. unfold fr2_XS.
    replace (fsz 2) with 256 in FX by reflexivity. replace (fshn 2) with 32 in FX by reflexivity.
    pose proof (Forall_inv FX) as A1. pose proof (Forall_inv (Forall_inv_tail FX)) as A2.
    pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail FX))) as A3. pose proof (Forall_inv (Forall_inv_tail (Forall_inv_tail (Forall_inv_tail FX)))) as A4.
    repeat apply Forall_cons; [exact A1| exact A2| exact A3| exact A4| apply Forall_nil].
  Qed.

