    intros LF m1 XS m m' RF FX CR MU. eapply (ACanaryReads_hi _ m m'); [exact CR| exact MU|].
    eapply Forall_impl; [| exact FX]. intros iv K. pose proof (scratch_facts H HH LF m1 [] iv RF K) as (_ & K1 & _). exact K1.
  Qed.

  Lemma acanary_scratch : forall LF m1 XS m m',
    as_RFS H LF m1 -> Forall (fs_scratch H LF) XS -> acanary m -> munch XS m m' -> wmono bsegs m m' -> acanary m'.
  Proof.
    intros LF m1 XS m m' RF FX [can CN] MU WM. exists can. eapply rw_cells_transport; [exact CN| exact MU| exact WM|].
